import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validators: WeakMap<Record<string, unknown>, ValidateFunction>;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileValidator(name: string, inputSchema: Record<string, unknown>): ValidateFunction {
    try {
      return new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]).compile(
        inputSchema
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool '${name}': ${message}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      validator = this.compileValidator(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validators: new WeakMap(),
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input against its schema; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.validatorFor(tool, definition);
    if (!validator(input)) {
      return this.invalidInput(name, validator.errors ?? []);
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    const cached = tool.validators.get(definition.inputSchema);
    if (cached) return cached;
    const validator = this.compileValidator(definition.name, definition.inputSchema);
    tool.validators.set(definition.inputSchema, validator);
    return validator;
  }

  private invalidInput(name: string, errors: ErrorObject[]): ToolResponse {
    const messages = errors.map(error => {
      const path = this.errorPath(error);
      const missing =
        error.keyword === 'required' &&
        typeof error.params === 'object' &&
        error.params !== null &&
        'missingProperty' in error.params &&
        typeof error.params.missingProperty === 'string'
          ? ` '${error.params.missingProperty}'`
          : '';
      return `${path}${missing} ${error.message ?? 'is invalid'}`;
    });
    log.warn('tool', 'input validation failed', {
      name,
      paths: errors.map(error => this.errorPath(error)),
      constraints: errors.map(error => error.keyword ?? 'unknown'),
    });
    return {result: `Tool '${name}' input invalid: ${messages.join('; ')}`};
  }

  private errorPath(error: ErrorObject): string {
    if (
      error.keyword === 'required' &&
      typeof error.params === 'object' &&
      error.params !== null &&
      'missingProperty' in error.params &&
      typeof error.params.missingProperty === 'string'
    ) {
      return `/${error.params.missingProperty}`;
    }
    const path = 'instancePath' in error && typeof error.instancePath === 'string' ? error.instancePath : '';
    if (!path) return '(root)';
    return path.startsWith('.') ? `/${path.slice(1).replaceAll('.', '/')}` : path;
  }
}
import {ToolRegistry} from './registry.js';
import {setLogger, type Logger} from '../../shared/logger.js';

describe('ToolRegistry input validation', () => {
  it('passes valid input and unlisted properties through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', extra: 'keep me'};
    let received: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async value => {
        received = value;
        return 'sunny';
      }
    );

    await registry.execute('get_weather', input);

    expect(received).toEqual(input);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const calls = {count: 0};
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: Object.freeze({
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        }),
      },
      async () => {
        calls.count += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls: calls.count,
      result: response.result,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      result: expect.any(String),
      mentionsRequiredField: true,
    });
  });

  it('logs the missing required property path and constraint', async () => {
    const warnings: Array<{message: string; fields?: Record<string, unknown>}> = [];
    const logger: Logger = {
      debug: () => undefined,
      info: () => undefined,
      warn: (category, message, fields) => {
        if (category === 'tool') warnings.push({message, fields});
      },
      error: () => undefined,
    };
    setLogger(logger);
    try {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
            required: ['location'],
          },
        },
        async () => 'sunny'
      );

      await registry.execute('get_weather', {});
    } finally {
      setLogger();
    }

    expect(warnings).toContainEqual({
      message: 'input validation failed',
      fields: {name: 'get_weather', paths: ['/location'], constraints: ['required']},
    });
  });

  it('rejects a wrong-typed property with its path and expected type without leaking the value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      executorCalls,
      result: response.result,
      namesField: response.result.includes('identifier'),
      namesExpectedType: response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
    }).toEqual({
      executorCalls: 0,
      result: expect.any(String),
      namesField: true,
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('logs the failing property path without the rejected value', async () => {
    const registry = new ToolRegistry();
    const warnings: Array<{message: string; fields?: Record<string, unknown>}> = [];
    const logger: Logger = {
      debug: () => undefined,
      info: () => undefined,
      warn: (category, message, fields) => {
        if (category === 'tool') warnings.push({message, fields});
      },
      error: () => undefined,
    };
    setLogger(logger);
    try {
      registry.register(
        {
          name: 'lookup_record',
          description: 'Look up a record',
          inputSchema: {
            type: 'object',
            properties: {identifier: {type: 'string'}},
          },
        },
        async () => 'found'
      );

      await registry.execute('lookup_record', {identifier: 123456789});
    } finally {
      setLogger();
    }

    expect(warnings).toEqual([
      {
        message: 'input validation failed',
        fields: {name: 'lookup_record', paths: ['/identifier'], constraints: ['type']},
      },
    ]);
  });

  it('rejects an uncompilable static schema at registration and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Broken weather tool',
          inputSchema: {type: 'not-a-json-schema-type'},
        },
        async () => 'sunny'
      )
    ).toThrow("Invalid inputSchema for tool 'broken_weather'");
  });

  it('validates each function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => {
        definitionCalls += 1;
        const property = definitionCalls === 2 ? 'location' : 'city';
        return {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {
            type: 'object',
            properties: {[property]: {type: 'string'}},
            required: [property],
          },
        };
      },
      async input => {
        inputs.push(input);
        return 'sunny';
      }
    );

    const first = await registry.execute('get_weather', {location: 'Berlin'});
    const second = await registry.execute('get_weather', {city: 'Paris'});

    expect({
      firstResult: first.result,
      secondResult: second.result,
      inputs,
    }).toEqual({
      firstResult: 'sunny',
      secondResult: 'sunny',
      inputs: [{location: 'Berlin'}, {city: 'Paris'}],
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.test.ts#L30), [acceptance](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property with its path and expected type without leaking the value](../../src/orchestration/tools/registry.test.ts#L99), [validated by: logs the failing property path without the rejected value](../../src/orchestration/tools/registry.test.ts#L134), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- An input that satisfies its schema keeps undeclared properties when it reaches the executor ([validated by: passes valid input and unlisted properties through unchanged](../../src/orchestration/tools/registry.test.ts#L5)).
- Validation log records name the failing property path and constraint, including the missing property for a `required` failure ([validated by: logs the missing required property path and constraint](../../src/orchestration/tools/registry.test.ts#L62)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- An invalid static schema is rejected synchronously at registration, and the error names the tool being registered ([validated by: rejects an uncompilable static schema at registration and names the tool](../../src/orchestration/tools/registry.test.ts#L172)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates each function-valued definition against its current schema](../../src/orchestration/tools/registry.test.ts#L187)).

## Orchestrator tool-loop recovery

- A tool call causes another provider round, and streamed chunks from both rounds remain in order ([validated by: runs another round after a tool call and streams both rounds in order](../../src/orchestration/chatOrchestrator.test.ts#L455)).
- A response that requests no tool stops after one provider round ([validated by: stops after one round when nothing asked for a tool](../../src/orchestration/chatOrchestrator.test.ts#L467)).
- A tool result rewrites an upserted entry's index to the session index ([validated by: appends an upserted entry to the session and rewrites its index to match](../../src/orchestration/chatOrchestrator.test.ts#L503)).
- A tool result that marks the assistant response handled emits suppression ([validated by: asks for suppression when the tool says the reply is already handled](../../src/orchestration/chatOrchestrator.test.ts#L520)).
- Text from each provider round is joined before the post-response hook runs ([validated by: joins the text of every round, not only the last](../../src/orchestration/chatOrchestrator.test.ts#L532)).
- Usage reported by an earlier provider round is retained when a later round reports none ([validated by: keeps the usage an earlier round reported when a later round reports none](../../src/orchestration/chatOrchestrator.test.ts#L554)).

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a rejected tool call to the provider so it can retry with corrected input](../../src/orchestration/chatOrchestrator.test.ts#L401), [acceptance](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
